      overviewCard('kpi-imbalance','Biến động giá',change==null?'—':`${change>=0?'+':''}${num(change,2)}%`,'So với giá đóng cửa phiên trước');
      overviewCard('kpi-valid','Phiên lịch sử mới nhất',latest?.trading_date||'—',latest?`${num(latest.high_price,0)} / ${num(latest.low_price,0)} đ cao/thấp`:'Chưa có nến OHLC');
      overviewChartHeading('spread-chart',`Giá đóng cửa lịch sử · ${chosen}`,'OHLC ngày SSI · di chuột để xem ngày và giá');
      lineChart(document.querySelector('#spread-chart'),[{name:chosen,rows,color:'#008A45'}],'close_price',`Giá đóng cửa ${chosen} · đồng/cổ phiếu`);
      overviewChartHeading('depth-chart',`Khối lượng giao dịch · ${chosen}`,'Cổ phiếu theo ngày · OHLC SSI');
      lineChart(document.querySelector('#depth-chart'),[{name:'Khối lượng',rows:rows.map(r=>({...r,value:r.volume})),color:'#68A92E'}],'value',`Khối lượng ${chosen} · cổ phiếu`);
