      const med=(arr)=>{arr=arr.filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number).sort((a,b)=>a-b);return arr.length?(arr[(arr.length-1)>>1]+arr[arr.length>>1])/2:null;};
      overviewCard('kpi-symbols','Mã có snapshot sổ lệnh',num(active.length,0),'Có báo giá SSI trong cửa sổ đang chọn');overviewCard('kpi-spread','Trung vị chênh lệch giá mua – bán (spread)',num(med(valid.map(r=>r.spread_bps))),'Điểm cơ bản (bps) · chênh lệch theo báo giá');overviewCard('kpi-depth','Trung vị tổng độ sâu sổ lệnh (total depth)',num(med(valid.map(r=>r.total_depth_value)),0),'Ba mức giá đầu · đơn vị giá × khối lượng');overviewCard('kpi-imbalance','Mất cân bằng khối lượng chờ (queue imbalance)',num(med(valid.map(r=>r.queue_imbalance)),3),'Khối lượng chờ mua so với chờ bán');overviewCard('kpi-valid','Ảnh chụp dữ liệu hợp lệ (snapshot)',rows.length?(valid.length/rows.length*100).toFixed(1)+'%':'—',`${num(valid.length,0)} / ${num(rows.length,0)} snapshot`);
