      lineChart(document.querySelector('#imbalance-chart'),series,'queue_imbalance','Mất cân bằng khối lượng chờ (queue imbalance) theo thời gian');
      lineChart(document.querySelector('#depth-chart'),series,'total_depth_value','Tổng độ sâu ba mức giá đầu (top-3 depth) theo thời gian');
