      document.querySelector('#orderbook').innerHTML=latest?window.table(['','Giá mua (bid)','Khối lượng mua (bid)','Giá bán (ask)','Khối lượng bán (ask)',''],[1,2,3].map(i=>[`<span class="side-bid">Giá mua (bid) ${i}</span>`,num(latest['bid_price_'+i]),num(latest['bid_volume_'+i],0),num(latest['ask_price_'+i]),num(latest['ask_volume_'+i],0),`<span class="side-ask">Giá bán (ask) ${i}</span>`])):'<div class="empty-state">Chưa có ảnh chụp dữ liệu (snapshot) cho mã này.</div>';
