  function rankTable(rows,key,type){const current=new Map(rows.map((r,i)=>[r.symbol,i+1])),previous=prevRanks[type], output=rows.map((r,i)=>{const old=previous.get(r.symbol),movement=old==null?'MỚI':old===i+1?'—':old>i+1?`▲ ${old-i-1}`:`▼ ${i+1-old}`;return [`<b class="rank-number">${i+1}</b>`,`<b>${esc(r.symbol)}</b>`,`<span class="rank-move ${movement.startsWith('▲')?'up':movement.startsWith('▼')?'down':''}">${movement}</span>`,num(r[key],key.includes('depth')?0:2),num(r.snapshot_count,0)];});prevRanks[type]=current;return window.table(['Hạng','Mã','Thay đổi thứ hạng','Trung vị','Số mẫu'],output);}
